/**
 * boulder-chunk-sweep.mjs — the two numbers the boulder probe rests on, REPRODUCIBLE.
 * ▶ node scratch/boulder-chunk-sweep.mjs
 *
 * ⭐ Neither of these belongs in prose: both can be checked by running something, so
 * this is the check and the report carries the command, not the figures.
 *   ① CHUNK-SEAM DETERMINISM — a stone generated by its own chunk must land in the
 *     same place when its NEIGHBOUR generates it. Prints the margin where that
 *     becomes exact. ⛔ There is no acceptable non-zero mismatch: a mismatch is a
 *     stone that pops as the camera moves.
 *   ② THE DART OVERSAMPLE — the dominant generation cost, swept against density so
 *     the trade is visible rather than asserted.
 */
import { shoreContext, chunkStones, verifySeams, CHUNK_M } from '../src/lib/shoreChunks.js'
import { demoShoreline, huronLikeCrest } from '../src/harness/boulders/heap.js'

const poly = demoShoreline({ length: 120 })
const mk = (oversample) => shoreContext({ poly, crestAt: huronLikeCrest, oversample })

console.log(`\n① SEAM DETERMINISM  (chunk ${CHUNK_M} m)`)
for (const margin of [1, 2, 3, 4]) {
  const r = verifySeams(mk(undefined), margin)
  const ok = r.missing === 0 && r.moved === 0
  console.log(`   margin ${margin}  checked ${String(r.checked).padStart(5)}  missing ${String(r.missing).padStart(3)}  moved ${String(r.moved).padStart(3)}  maxΔ ${r.maxDelta}  ${ok ? '✅ exact' : '⛔ MISMATCH'}`)
}

console.log(`\n② DART OVERSAMPLE  (cost vs density; seams must stay exact at every row)`)
for (const os of [45, 20, 10, 5]) {
  const warm = mk(os); chunkStones(warm, 5, 2)
  const ctx = mk(os)
  const t0 = performance.now()
  let stones = 0, n = 0
  for (let i = 1; i < ctx.nChunks - 1; i++) { stones += chunkStones(ctx, i, 2).length; n++ }
  const ms = (performance.now() - t0) / n
  const seam = verifySeams(mk(os), 2)
  console.log(`   oversample ${String(os).padStart(2)}  ${ms.toFixed(1).padStart(6)} ms/chunk  ${String(Math.round((stones / (n * CHUNK_M)) * 100)).padStart(5)} stones/100 m  seams ${seam.missing + seam.moved === 0 ? '✅' : '⛔'}`)
}
console.log('')
